/**
 * Krepselio eilutes zymejimas. ps_pet_id/ps_source ateina POST duomenimis
 * is musu „Idėti i krepseli" — WooCommerce AJAX endpointas juos perduoda.
 */
public static function tag_cart_item( $data, $product_id, $variation_id ) {
	$src = self::valid_source( isset( $_REQUEST['ps_source'] ) ? $_REQUEST['ps_source'] : '' );
	if ( ! $src ) { return $data; }
	$pet = isset( $_REQUEST['ps_pet_id'] ) ? (int) $_REQUEST['ps_pet_id'] : 0;
	$data['ps_pet_id'] = $pet ?: null;
	$data['ps_source'] = $src;

	// „Idejo i krepseli" ivykis. Krepseliai nesaugomi, tad be sito
	// tureciau tik „apmokejo" puse ir negaleciau paskaiciuoti konversijos.
	global $wpdb;
	$pid  = $variation_id ? (int) $variation_id : (int) $product_id;
	$prod = function_exists( 'wc_get_product' ) ? wc_get_product( $pid ) : null;
	$qty  = isset( $_REQUEST['quantity'] ) ? max( 1, (int) $_REQUEST['quantity'] ) : 1;
	$wpdb->insert( self::table(), array(
		'pet_id'      => $pet ?: null,
		'user_id'     => get_current_user_id() ?: null,
		'product_id'  => $pid,
		'qty'         => $qty,
		'unit_price'  => $prod ? (float) wc_get_price_to_display( $prod ) : null,
		'source'      => $src,
		'session_key' => self::session_key(),
		'created_at'  => current_time( 'mysql' ),
	) );
	return $data;
}

