private static function session_key() {
	if ( function_exists( 'WC' ) && WC()->session ) {
		$k = WC()->session->get_customer_id();
		if ( $k ) { return substr( (string) $k, 0, 64 ); }
	}
	$uid = get_current_user_id();
	return $uid ? ( 'u' . $uid ) : null;
}

